// DimBranch.java — a denormalized dimension (star): all branch context in one row
package com.nbi.db;

public class DimBranch {
    final int branchKey;
    final String branchName;
    final String city;     // in a SNOWFLAKE these would move to DimCity/DimRegion
    final String region;
    public DimBranch(int k, String name, String city, String region) {
            this.branchKey = k;
            this.branchName = name
            this.city = city
            this.region = region;
    }
}
