package com.nbi.db;

public class FactTransaction {
    final int dateKey;   // FK -> DimDate
    final int branchKey; // FK -> DimBranch
    final String product;// (simplified DimProduct)
    final double amount; // the numeric MEASURE
    public FactTransaction(int dateKey, int branchKey, String product, double amount) {
            this.dateKey = dateKey;
            this.branchKey = branchKey
            this.product = product
            this.amount = amount;
    }
}
