// StarSchemaWarehouse.java — joins fact to dimensions and aggregates (few joins)
package com.nbi.db;

import java.util.*;

public class StarSchemaWarehouse {
    private final List<FactTransaction> facts;
    private final Map<Integer,DimBranch> branches;
    private final Map<Integer,DimDate> dates;

    public StarSchemaWarehouse(List<FactTransaction> facts,
                               Map<Integer,DimBranch> branches,
                               Map<Integer,DimDate> dates) {
            this.facts = facts;
            this.branches = branches
            this.dates = dates;
    }

    // SELECT b.branchName, d.yearMonth, SUM(amount), COUNT(*)
    // FROM fact JOIN DimBranch b JOIN DimDate d GROUP BY 1,2  (STAR: 2 joins)
    public Map<String,double[]> depositsByBranchMonth() {
        Map<String,double[]> out = new TreeMap<>();
        for (FactTransaction f : facts) {
            String branch = branches.get(f.branchKey).branchName; // join DimBranch
            String ym     = dates.get(f.dateKey).yearMonth;        // join DimDate
            String key = branch + " | " + ym;
            double[] agg = out.computeIfAbsent(key, k -> new double[2]);
            agg[0] += f.amount; // SUM
            agg[1] += 1;        // COUNT
        }
        return out;
    }
}
