// Demo.java — runs star aggregation + prints logical vs physical model notes
package com.nbi.db;

import java.util.*;

public class Demo {
    public static void main(String[] args) {
        Map<Integer,DimBranch> branches = Map.of(
            1, new DimBranch(1,"Connaught Place","New Delhi","North"),
            2, new DimBranch(2,"Bandra","Mumbai","West"));
        Map<Integer,DimDate> dates = Map.of(
            20260115, new DimDate(20260115,"2026-01"),
            20260220, new DimDate(20260220,"2026-02"));

        List<FactTransaction> facts = List.of(
            new FactTransaction(20260115,1,"SAV", 10000),
            new FactTransaction(20260115,1,"FD",   5000),
            new FactTransaction(20260220,2,"SAV",  8000),
            new FactTransaction(20260220,1,"SAV",  2000));

        var wh = new StarSchemaWarehouse(facts, branches, dates);
        System.out.println("STAR aggregation (fact + 2 dim joins): branch|month -> {sum, count}");
        wh.depositsByBranchMonth().forEach((k,v) ->
            System.out.printf("  %-28s sum=%.0f count=%.0f%n", k, v[0], v[1]));

        System.out.println("\n-- Star vs Snowflake --");
        System.out.println("  STAR:      Fact -> DimBranch(name,city,region)         [1 join to branch]");
        System.out.println("  SNOWFLAKE: Fact -> DimBranch -> DimCity -> DimRegion   [3 joins, less redundancy]");

        System.out.println("\n-- Logical vs Physical model --");
        System.out.println("  LOGICAL (DBMS-independent): entities Fact/Branch/Date/Product; FKs; relationships");
        System.out.println("  PHYSICAL (DBMS-specific):   amount NUMERIC(18,2); index on (branchKey,dateKey);");
        System.out.println("                              RANGE PARTITION fact BY dateKey; columnar storage");
    }
}
